from pathlib import Path
s=Path('browser-vikings63-route.js').read_text(encoding='utf-8').replace('3008','3017').replace('vikings63RouteCapture','vikingsFlight70d').replace('vikings63-route-','vikings70-flight-')
s=s.replace("await page.locator('#play-refraction').click();","await page.locator('#play-refraction').click();if((await page.locator('#zoom').textContent()).startsWith('1'))await page.locator('#zoom').click();")
s=s.replace("async(_,name)=>page.screenshot({path:'output/playwright/vikings70-flight-'+name+'.png'})", """async(_,name)=>{await page.screenshot({path:'output/playwright/vikings70-flight-'+name+'.png'});if(['draft','brake'].includes(name)){await page.locator('#pause').click();await page.locator('#zoom').click();await page.waitForTimeout(300);await page.screenshot({path:'output/playwright/vikings70-flight-'+name+'-1x.png'});await page.setViewportSize({width:390,height:844});await page.waitForTimeout(300);await page.screenshot({path:'output/playwright/vikings70-flight-'+name+'-mobile.png'});await page.locator('#zoom').click();await page.waitForTimeout(300);await page.screenshot({path:'output/playwright/vikings70-flight-'+name+'-mobile-2x.png'});await page.setViewportSize({width:1440,height:900});await page.waitForTimeout(300);await page.locator('#pause').click();}}""")
s=s[:s.index("await move(2,850)")]+"await move(2,750);await until(()=>read().heroes[2].vy>0);await capture('brake');return {health:read().heroes.map(h=>h.hp),time:read().time,olaf:read().heroes[2]};\n });return{result,errors};\n}\n"
Path('browser-vikings70-flight.js').write_text(s,encoding='utf-8')
